class_name EconomyManager

signal job_completed(job_id: String, pay: float)
signal job_failed(job_id: String, reason: String)

const CONFIG_PATH := "res://data/economy/economy.json"

var clock: WorldClock
var config: Dictionary = {}
var jobs: Dictionary = {}

func _ready() -> void:
    _load_config()

func configure(c: WorldClock) -> void:
    clock = c

func complete_job(job_id: String) -> bool:
    if not jobs.has(job_id):
        job_failed.emit(job_id, "unknown_job")
        return false
    var job: Dictionary = jobs[job_id]
    var cost := float(job.get("energy_cost", 0.0))
    if GameState.energy < cost:
        job_failed.emit(job_id, "low_energy")
        return false
    GameState.set_stat("energy", GameState.energy - cost)
    GameState.add_money(float(job.get("pay", 0.0)))
    if clock:
        clock.skip_minutes(int(job.get("duration_game_minutes", 0)))
    job_completed.emit(job_id, float(job.get("pay", 0.0)))
    return true

func get_job(job_id: String) -> Dictionary:
    return jobs.get(job_id, {})

func _load_config() -> void:
    if not FileAccess.file_exists(CONFIG_PATH):
        return
    var f := FileAccess.open(CONFIG_PATH, FileAccess.READ)
    if f == null:
        return
    var parsed = JSON.parse_string(f.get_as_text())
    if typeof(parsed) != TYPE_DICTIONARY:
        return
    config = parsed
    for entry in parsed.get("jobs", []):
        if typeof(entry) == TYPE_DICTIONARY:
            jobs[str(entry.get("id",""))] = entry

