class_name FuelPurchaseSystem

signal fuel_purchased(percent_added: float, cost: float)
signal purchase_rejected(reason: String)

const CONFIG_PATH := "res://data/fuel/fuel_config.json"

var config: Dictionary = {}

func _ready() -> void:
    _load_config()

func price_for(percent: float) -> float:
    var clamped := clampf(percent, 0.0, 100.0)
    return clamped * float(config.get("price_per_percent", 0.10))

func max_affordable_percent() -> float:
    var unit_price := float(config.get("price_per_percent", 0.10))
    if unit_price <= 0.0:
        return 0.0
    return clampf(GameState.money / unit_price, 0.0, 100.0 - GameState.fuel)

func purchase(percent: float) -> bool:
    if GameState.fuel_shortage:
        purchase_rejected.emit("fuel_shortage")
        return false

    var min_percent := float(config.get("minimum_purchase_percent", 5.0))
    var capacity_left := maxf(0.0, 100.0 - GameState.fuel)
    var requested := minf(percent, capacity_left)

    if requested < min_percent and capacity_left >= min_percent:
        purchase_rejected.emit("below_minimum")
        return false

    if requested <= 0.0:
        purchase_rejected.emit("tank_full")
        return false

    var cost := price_for(requested)
    if GameState.money < cost:
        purchase_rejected.emit("insufficient_funds")
        return false

    GameState.add_money(-cost)
    GameState.set_stat("fuel", GameState.fuel + requested)
    fuel_purchased.emit(requested, cost)
    return true

func purchase_max_affordable() -> bool:
    var amount := max_affordable_percent()
    if amount <= 0.0:
        purchase_rejected.emit("insufficient_funds")
        return false
    return purchase(amount)

func presets() -> Array:
    var values = config.get("presets", [10,25,50,100])
    return values if typeof(values) == TYPE_ARRAY else [10,25,50,100]

func _load_config() -> void:
    if not FileAccess.file_exists(CONFIG_PATH):
        return
    var f := FileAccess.open(CONFIG_PATH, FileAccess.READ)
    if f == null:
        return
    var parsed = JSON.parse_string(f.get_as_text())
    if typeof(parsed) == TYPE_DICTIONARY:
        config = parsed

