class_name JobBoard

@export var preferred_job_id := "cafe_shift"
var job_system: JobSystem

func _ready() -> void:
    add_to_group("interactable")
    prompt_ar = "اسأل على خدمة"

func configure(system: JobSystem) -> void:
    job_system = system

func can_interact(_actor: Node) -> bool:
    return enabled and job_system != null

func interact(actor: Node) -> void:
    if not can_interact(actor):
        return

    if job_system.selected_job_id.is_empty():
        var offers = job_system.available_offers(GameState.current_district)
        if offers.is_empty():
            interacted.emit(actor)
            return

        var chosen: Dictionary = offers[0]
        for offer in offers:
            if str(offer.get("id","")) == preferred_job_id:
                chosen = offer
                break
        job_system.select_offer(str(chosen.get("id","")))
    else:
        job_system.complete_selected_job()

    if GameState.missions.get("find_job") == "active":
        get_tree().call_group("mission_manager", "complete", "find_job")
    interacted.emit(actor)

